import io
import json
import urllib.error
from unittest.mock import Mock
from openai_client import OpenAIClient, OpenAIError, _NoRedirects

client = OpenAIClient('test-key')
completed = {'status': 'completed', 'output': [{'type': 'reasoning'}, {'type': 'message', 'role': 'assistant', 'content': [{'type': 'output_text', 'text': 'Hello '}, {'type': 'output_text', 'text': 'world'}]}]}
def reply(value):
    client._opener = Mock()
    client._opener.open.return_value = io.BytesIO(json.dumps(value).encode())
reply(completed)
assert client.respond('private café', model='test-model', max_output_tokens=20) == 'Hello world'
args, kwargs = client._opener.open.call_args
req = args[0]
assert req.full_url == 'https://api.openai.com/v1/responses'
assert req.method == 'POST'
assert req.get_header('Authorization') == 'Bearer test-key'
assert json.loads(req.data) == {'model': 'test-model', 'input': 'private café', 'store': False, 'max_output_tokens': 20}
assert kwargs == {'timeout': 60.0}
for value in ({'status': 'incomplete'}, {'status': 'completed', 'output': []}, {'status': 'completed', 'output': [{'type': 'message', 'role': 'assistant', 'content': [{'type': 'refusal', 'refusal': 'private'}]}]}, []):
    reply(value)
    try: client.respond('private', model='test-model')
    except OpenAIError as exc: assert 'private' not in str(exc)
    else: raise AssertionError('Expected response error')
for error in (urllib.error.HTTPError(req.full_url, 401, 'private', {}, io.BytesIO(b'private')), urllib.error.URLError('private'), TimeoutError('private')):
    client._opener.open.side_effect = error
    try: client.respond('private', model='test-model')
    except OpenAIError as exc:
        assert 'private' not in str(exc)
        assert exc.__suppress_context__
        if isinstance(error, urllib.error.HTTPError): assert exc.status_code == 401
    else: raise AssertionError('Expected transport error')
client._opener = Mock()
client._opener.open.return_value = io.BytesIO(b'not json private')
try: client.respond('private', model='test-model')
except OpenAIError as exc: assert 'private' not in str(exc)
else: raise AssertionError('Expected JSON error')
for timeout in (0, -1, float('nan'), float('inf'), True):
    try: OpenAIClient('test-key', timeout=timeout)
    except ValueError: pass
    else: raise AssertionError('Expected validation error')
assert _NoRedirects().redirect_request(req, None, 302, '', {}, 'https://example.com') is None
print('Passed mocked request, extraction, refusal, incomplete response, HTTP/network error, invalid JSON, validation, and redirect checks.')
PY"

